import sys, heapq

def main():
    data = sys.stdin.read().split()
    r, c = int(data[0]), int(data[1])
    h = [[int(data[2 + i * c + j]) for j in range(c)] for i in range(r)]
    seen = [[False] * c for _ in range(r)]
    heap = []
    for i in range(r):
        for j in range(c):
            if i == 0 or j == 0 or i == r - 1 or j == c - 1:
                seen[i][j] = True
                heap.append((h[i][j], i, j))
    heapq.heapify(heap)
    total = 0
    while heap:
        lvl, i, j = heapq.heappop(heap)
        for ni, nj in ((i + 1, j), (i - 1, j), (i, j + 1), (i, j - 1)):
            if 0 <= ni < r and 0 <= nj < c and not seen[ni][nj]:
                seen[ni][nj] = True
                if h[ni][nj] < lvl:
                    total += lvl - h[ni][nj]
                    heapq.heappush(heap, (lvl, ni, nj))
                else:
                    heapq.heappush(heap, (h[ni][nj], ni, nj))
    print(total)

main()

